WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_doc_plan'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '方案指导类', 'kp-sl-doc-plan', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "方案指导类公文"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结构：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "宏观指导与微观操作结合。目的明确，对策详尽。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“工作方案”、“指导意见”、“通知”、“对策建议”。是为了下发给下级部门指导工作的。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、答题骨架"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "发文缘由：当前面临什么急需解决的问题，或者为了贯彻什么上级精神。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "总体要求（可选）：指导思想、工作目标。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "具体措施（最核心）：按照逻辑顺序（如：排查-整改-监督-长效），详细列出步骤一二三四。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "保障措施（兜底）：加强组织领导、资金保障、考核问责等。"}]}]}]}]}$$ AS jsonb), NULL, '方案指导类的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "公文写作", "方案指导"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_doc_plan", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
